import React,{useState,useEffect,useRef} from 'react';
import {createRoot} from 'react-dom/client';
import {LayoutDashboard,ClipboardCheck,Ship,FileText,FolderOpen,Users,ChartNoAxesCombined,Settings,Search,Bell,ChevronDown,ChevronRight,ArrowRight,ArrowUpRight,ArrowDownLeft,Plus,X,Check,CheckCheck,Clock,CalendarDays,Download,Upload,SlidersHorizontal,Plane,Truck,Package,Anchor,Building2,ShieldCheck,TriangleAlert,ExternalLink,Menu,RotateCcw,Info,History,Save,Mail,Globe,Ellipsis,MoveRight} from 'lucide-react';
import {TODAY,STATUS,CUSTOMS,MODES,DIRECTIONS,DOC_STATUS,money,shortDate,daysUntil,checklist,transitionError,alertsFor,timeline,validCuit,csvCell,initialState} from './domain.mjs';
import './styles.css';
import ClientPortal,{DemoViewSelector} from './ClientPortal.jsx';
import {DEMO_VIEWS,DEMO_CUSTOMERS,migrateDemoData,clientOperations,sharedDocument} from './client-access.mjs';
const STORAGE='atlas-operaciones-demo-v1';
const NAV=[['dashboard','Panel general',LayoutDashboard],['tasks','Centro de tareas',ClipboardCheck],['shipments','Embarques',Ship],['quotes','Cotizaciones',FileText],['documents','Documentos',FolderOpen],['customers','Clientes',Users],['reports','Resumen de costos',ChartNoAxesCombined]];
const uid=()=>Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join('');
const modeIcon=m=>m==='AIR'?Plane:m==='ROAD'?Truck:Ship;
function Badge({status,custom=false}){return <span className={'badge '+status.toLowerCase()}><i/>{custom?CUSTOMS[status]:STATUS[status]||status}</span>}
function Field({label,children,hint,wide=false}){return <label className={wide?'field wide':'field'}><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>}
function Modal({title,subtitle,children,onClose,wide=false}){const ref=useRef(null);useEffect(()=>{const before=document.activeElement;const el=ref.current;el?.focus();const old=document.body.style.overflow;document.body.style.overflow='hidden';const handler=e=>{if(e.key==='Escape')onClose();if(e.key==='Tab'){const nodes=el.querySelectorAll('button:not(:disabled),input,select,textarea,a[href],[tabindex="0"]');const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===el)){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}};document.addEventListener('keydown',handler);return()=>{document.body.style.overflow=old;document.removeEventListener('keydown',handler);before?.focus();}},[]);return <div className="modal-backdrop" onClick={e=>e.target===e.currentTarget&&onClose()}><section className={'modal '+(wide?'modal-wide':'')} role="dialog" aria-modal="true" aria-labelledby="modal-title" ref={ref} tabIndex={-1}><div className="modal-head"><div><h2 id="modal-title">{title}</h2>{subtitle&&<p>{subtitle}</p>}</div><button className="icon-btn" onClick={onClose} aria-label="Cerrar"><X size={20}/></button></div>{children}</section></div>}
function App(){
 const [data,setData]=useState(()=>{try{const d=JSON.parse(localStorage.getItem(STORAGE));if(d?.version===1&&Array.isArray(d.operations)&&Array.isArray(d.tasks)&&Array.isArray(d.quotes))return migrateDemoData(d);}catch{}return migrateDemoData(initialState());});
 const [page,setPage]=useState('dashboard'),[query,setQuery]=useState(''),[direction,setDirection]=useState('ALL'),[filter,setFilter]=useState('ALL'),[selected,setSelected]=useState(data.operations[0]?.id),[modal,setModal]=useState(null),[detailTab,setDetailTab]=useState('summary'),[toast,setToast]=useState(''),[mobile,setMobile]=useState(false),[showAll,setShowAll]=useState(false),[storageError,setStorageError]=useState(false);
 const [view,setView]=useState(()=>{const requested=new URLSearchParams(location.search).get('vista');return DEMO_VIEWS.some(v=>v.id===requested)?requested:'atlas';});
 const changeView=id=>{if(!DEMO_VIEWS.some(v=>v.id===id))return;setModal(null);setMobile(false);setView(id);const url=new URL(location.href);if(id==='atlas')url.searchParams.delete('vista');else url.searchParams.set('vista',id);history.replaceState(null,'',url);};
 const toastTimer=useRef();
 useEffect(()=>{try{localStorage.setItem(STORAGE,JSON.stringify(data));setStorageError(false);}catch{setStorageError(true);}},[data]);
 const notify=text=>{setToast(text);clearTimeout(toastTimer.current);toastTimer.current=setTimeout(()=>setToast(''),4200);};
 const ops=data.operations,alerts=alertsFor(ops,data.tasks),active=ops.find(o=>o.id===selected)||ops[0];
 const filtered=ops.filter(o=>(direction==='ALL'||o.direction===direction)&&(filter==='ALL'||(filter==='CUSTOMS_PENDING'?['ARRIVED','CUSTOMS'].includes(o.status)&&o.customs!=='RELEASED':o.status===filter))&&(o.id+' '+o.customer+' '+o.origin+' '+o.destination+' '+o.booking+' '+o.container).toLowerCase().includes(query.toLowerCase()));
 const pendingTasks=data.tasks.filter(t=>!t.done);
 const navigate=p=>{setPage(p);setQuery('');setFilter('ALL');setDirection('ALL');setMobile(false);setShowAll(false);};
 const openFile=(id,tab='summary')=>{setSelected(id);setDetailTab(tab);setModal('detail');};
 const updateOp=(id,patch,message)=>{setData(prev=>({...prev,operations:prev.operations.map(o=>o.id===id?{...o,...patch,history:[{date:new Date().toISOString(),text:message,by:'Usuario demo'},...o.history]}:o)}));notify('Cambios guardados en este navegador');};
 const toggleTask=id=>{setData(p=>({...p,tasks:p.tasks.map(t=>t.id===id?{...t,done:!t.done}:t)}));};
 const exportCsv=(rows,name)=>{const blob=new Blob(['\ufeff'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);notify('Archivo exportado');};
 const exportOps=()=>exportCsv([['Referencia','Cliente','Operación','Modalidad','Origen','Destino','Estado transporte','Estado aduanero','ETA','ATA','Incoterm','Lugar convenido','Límite días libres','Límite almacenaje'],...filtered.map(o=>[o.id,o.customer,DIRECTIONS[o.direction],MODES[o.mode],o.origin,o.destination,STATUS[o.status],CUSTOMS[o.customs],o.eta,o.ata,o.incoterm,o.namedPlace,o.freeUntil,o.storageUntil])],'Atlas_Cargo_Embarques_DEMO.csv');
 const table=(limit)=> <><div className="table-scroll"><table className="shipment-table"><thead><tr><th>Embarque / cliente</th><th>Ruta</th><th>Estado</th><th>ETA</th><th aria-label="Abrir"/></tr></thead><tbody>{filtered.slice(0,limit||999).map(o=>{const Icon=modeIcon(o.mode);return <tr key={o.id} className={active?.id===o.id?'selected':''} onClick={()=>setSelected(o.id)}><td><button className="ref-link" onClick={e=>{e.stopPropagation();openFile(o.id);}}>{o.id}</button><small>{o.customer}</small></td><td><div className="route-cell"><span className="mode-square"><Icon size={16}/></span><span>{o.origin}<MoveRight size={12}/>{o.destination}<small className={o.direction==='EXPORT'?'export-text':''}>{DIRECTIONS[o.direction]} · {MODES[o.mode]}</small></span></div></td><td><Badge status={o.status}/></td><td><span className="eta-text">{shortDate(o.eta)}</span><small>{o.ata?'Arribó '+shortDate(o.ata):'Estimada'}</small></td><td><button className="icon-btn" onClick={()=>openFile(o.id)} aria-label={'Abrir '+o.id}><ChevronRight size={17}/></button></td></tr>})}</tbody></table>{!filtered.length&&<div className="empty"><Search/><h3>No encontramos embarques</h3><p>Probá otra referencia, cliente o filtro.</p><button className="btn" onClick={()=>{setQuery('');setDirection('ALL');setFilter('ALL');}}>Limpiar filtros</button></div>}</div><div className="table-foot"><span>{Math.min(filtered.length,limit||999)} de {filtered.length} embarques</span>{page==='dashboard'?<button onClick={()=>navigate('shipments')}>Ver todos los embarques <ArrowRight size={14}/></button>:<span>Datos de demostración</span>}</div></>;
 const taskList=(tasks,compact=false)=><div className="task-list">{tasks.map(t=><div className={'task-row '+(t.done?'task-done':'')} key={t.id}><button className={'checkbox '+(t.done?'checked':'')} aria-label={(t.done?'Reabrir ':'Completar ')+t.title} onClick={()=>toggleTask(t.id)}>{t.done&&<Check size={13}/>}</button><div className="task-copy"><strong>{t.title}</strong><span><button className="text-link" onClick={()=>openFile(t.op)}>{t.op}</button><i>·</i>{t.owner}</span></div><span className={'task-date '+(daysUntil(t.due)<1&&!t.done?'soon':'')}><Clock size={13}/>{daysUntil(t.due)===0?'Hoy':shortDate(t.due)}</span>{!compact&&<span className={'priority '+(t.priority==='Alta'?'high':'')}>{t.priority}</span>}</div>)}{!tasks.length&&<div className="empty small"><CheckCheck/><p>No hay tareas en esta vista.</p></div>}</div>;
 const title=({dashboard:'Tu operación, bajo control.',shipments:'Todos tus embarques.',tasks:'Cada pendiente, en su lugar.',quotes:'Cotizaciones que avanzan.',documents:'Todo en un solo archivo.',customers:'Tus clientes, conectados.',reports:'Los números de tu operación.',settings:'Tu espacio de trabajo.'})[page];
 const clientProfile=DEMO_VIEWS.find(v=>v.id===view&&v.customerId);
 if(clientProfile)return <ClientPortal key={view} profile={clientProfile} operations={clientOperations(ops,clientProfile.customerId)} onViewChange={changeView} Modal={Modal} Badge={Badge} onDownload={async(opId,docId)=>{const doc=sharedDocument(ops,clientProfile.customerId,opId,docId);if(!doc?.fileId)return 'El documento no está disponible para este perfil.';try{const row=await fileStore('get',doc.fileId);if(!row?.file)return 'El archivo ya no está disponible en este navegador.';const a=document.createElement('a');a.href=URL.createObjectURL(row.file);a.download=doc.fileName||doc.label;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);return 'Descarga iniciada.';}catch{return 'No se pudo descargar el documento.';}}}/>;
 return <div className="app-shell">
 <aside className={'sidebar '+(mobile?'mobile-open':'')}><a className="brand" href="#" onClick={e=>{e.preventDefault();navigate('dashboard');}}><img src="/brand/logo-dark.png" alt="Atlas Cargo"/><span>PLATAFORMA OPERATIVA</span></a><div className="workspace-select"><span className="workspace-icon"><Building2 size={18}/></span><span><strong>Atlas Cargo SRL</strong><small>Buenos Aires, Argentina</small></span><span className="workspace-dot"/></div><div className="nav-label">ESPACIO DE TRABAJO</div><nav>{NAV.map(([id,label,Icon])=><button key={id} className={page===id?'nav-item active':'nav-item'} onClick={()=>navigate(id)}><Icon size={19}/><span>{label}</span>{id==='tasks'&&<em>{pendingTasks.length}</em>}</button>)}</nav><div className="sidebar-bottom"><div className="demo-side"><span className="demo-orbit"><Globe size={20}/></span><strong>Una vista de lo que viene.</strong><p>Explorá tu nueva plataforma con operaciones de ejemplo.</p><button onClick={()=>setModal('about')}>Conocer esta versión <ArrowUpRight size={14}/></button></div><button className={'nav-item '+(page==='settings'?'active':'')} onClick={()=>navigate('settings')}><Settings size={18}/><span>Configuración</span></button><div className="sidebar-user"><span className="avatar">AC</span><div><strong>Equipo Atlas Cargo</strong><small>Entorno de demostración</small></div><ShieldCheck size={17}/></div></div></aside>
 {mobile&&<button className="mobile-scrim" onClick={()=>setMobile(false)} aria-label="Cerrar menú"/>}
 <div className="main-shell"><header className="topbar"><button className="icon-btn mobile-toggle" aria-label="Abrir menú" onClick={()=>setMobile(true)}><Menu/></button><div className="breadcrumb">Workspace <ChevronRight size={13}/><strong>{NAV.find(x=>x[0]===page)?.[1]||'Configuración'}</strong></div><div className="global-search"><Search size={17}/><input aria-label="Buscar embarques" placeholder="Buscar embarque, cliente o referencia..." value={query} onChange={e=>{setQuery(e.target.value);if(!['dashboard','shipments'].includes(page))setPage('shipments');}}/><kbd>⌕</kbd></div><DemoViewSelector value={view} onChange={changeView}/><div className="top-actions"><button className="demo-badge" onClick={()=>setModal('about')}><span/>MODO DEMO</button><button className="notification icon-btn" aria-label={'Ver '+alerts.length+' alertas'} onClick={()=>setModal('alerts')}><Bell size={19}/>{alerts.length>0&&<i/>}</button><span className="top-divider"/><span className="avatar light">MD</span></div></header>
 <main className="main-content"><div className="page-heading"><div><p className="eyebrow">ATLAS CARGO · OPERACIONES INTERNACIONALES</p><h1>{title}</h1><p className="subtitle">{page==='dashboard'?'Embarques, documentación y equipo. Todo conectado.':page==='shipments'?'Del primer contacto a la entrega. Seguí cada etapa.':page==='documents'?'Control documental por operación, modalidad y estado de revisión.':page==='reports'?'Compras, ventas y margen operativo estimado en USD.':'Organizá el trabajo y mantené el control de cada operación.'}</p></div><div className="heading-actions">{page==='dashboard'&&<span className="today"><CalendarDays size={15}/>30 oct, 2026</span>}{['dashboard','shipments'].includes(page)&&<button className="btn primary" onClick={()=>setModal('newOperation')}><Plus size={17}/>Nuevo embarque</button>}{page==='tasks'&&<button className="btn primary" onClick={()=>setModal('newTask')}><Plus size={17}/>Nueva tarea</button>}{page==='quotes'&&<button className="btn primary" onClick={()=>setModal('newQuote')}><Plus size={17}/>Nueva cotización</button>}{page==='documents'&&<button className="btn primary" onClick={()=>openFile(active.id,'documents')}><Upload size={17}/>Cargar documento</button>}</div></div>
 {storageError&&<div className="storage-error" role="alert">No se pudieron guardar los cambios: el almacenamiento del navegador está lleno o bloqueado. Exportá los datos antes de cerrar.</div>}
 {page==='dashboard'&&<>
 <section className="kpi-grid">{[[Ship,'En tránsito',ops.filter(o=>o.status==='IN_TRANSIT').length,'Hacia su próximo destino','blue'],[Building2,'En aduana',ops.filter(o=>['CUSTOMS','ARRIVED'].includes(o.status)&&o.customs!=='RELEASED').length,'Pendientes de libramiento','amber'],[Package,'Entregados',ops.filter(o=>o.status==='DELIVERED').length,'Operaciones completadas','green'],[ClipboardCheck,'Tareas pendientes',pendingTasks.length,`${pendingTasks.filter(t=>daysUntil(t.due)===0).length} para resolver hoy`,'red']].map(([Icon,label,num,sub,color],i)=><button key={label} className={'kpi '+color} onClick={()=>{if(i===3)navigate('tasks');else{navigate('shipments');if(i===0)setFilter('IN_TRANSIT');if(i===2)setFilter('DELIVERED');if(i===1){setFilter('CUSTOMS_PENDING');setQuery('');}}}}><div className="kpi-top"><span>{label}</span><div className="kpi-icon"><Icon size={21}/></div></div><strong>{String(num).padStart(2,'0')}</strong><div className="kpi-caption"><span className="dot"/>{sub}<ArrowUpRight size={14}/></div></button>)}</section>
 <button className="attention-strip" onClick={()=>setModal('alerts')}><span className="attention-icon"><TriangleAlert size={18}/></span><strong>Que no se te pase.</strong><span>{alerts.length} alertas operativas requieren seguimiento.</span><b>Revisar alertas <ArrowRight size={15}/></b></button>
 <div className="dashboard-grid"><div className="dashboard-left"><section className="panel"><div className="panel-heading"><div><h2>Últimos embarques <span className="count-pill">{ops.length}</span></h2><p>Visibilidad de punta a punta.</p></div><button className="icon-btn" aria-label="Exportar embarques" onClick={exportOps}><Download size={17}/></button></div><div className="table-tools"><div className="segmented">{[['ALL','Todos'],['IMPORT','Importación'],['EXPORT','Exportación']].map(([v,l])=><button className={direction===v?'active':''} key={v} onClick={()=>setDirection(v)}>{l}</button>)}</div><button className="filter-btn" onClick={()=>setModal('filters')}><SlidersHorizontal size={14}/>Filtros{filter!=='ALL'&&<i/>}</button></div>{table(5)}</section>
 <section className="panel tasks-panel"><div className="panel-heading"><h2>Lo próximo en tu agenda</h2><button className="text-link" onClick={()=>navigate('tasks')}>Ver tareas <ArrowRight size={14}/></button></div>{taskList(pendingTasks.slice(0,3),true)}</section></div>
 <div className="dashboard-right">{active&&<section className="panel tracking"><div className="panel-heading"><h2>Seguimiento del embarque</h2><span className="live-dot"/></div><div className="tracking-content"><div className="tracking-ref"><div><span className="eyebrow">REFERENCIA</span><h3>{active.id}</h3></div><Badge status={active.status}/></div><p className="tracking-client">{active.customer}</p><div className="route-visual"><div><strong>{active.originCode||active.origin.slice(0,3).toUpperCase()}</strong><span>{active.origin}</span></div><div className="route-line"><span/>{React.createElement(modeIcon(active.mode),{size:20})}<span/></div><div><strong>{active.destinationCode||active.destination.slice(0,3).toUpperCase()}</strong><span>{active.destination}</span></div></div><div className="shipment-meta">{React.createElement(modeIcon(active.mode),{size:14})}{MODES[active.mode]}<i>·</i>{active.container?.replace('DEMO · ','')||active.incoterm}</div><div className="timeline">{timeline(active).map(s=><div className={'timeline-step '+(s.done?'done':s.current?'current':'')} key={s.key}><span className="timeline-node">{s.done&&<Check size={12}/>}</span><div><strong>{s.label}</strong><small>{s.date?shortDate(s.date):s.key==='arrival'&&active.status==='IN_TRANSIT'?'En tránsito · ETA '+shortDate(s.expected):s.current?'Próximo hito':'Pendiente'}</small></div></div>)}</div><div className="eta-box"><CalendarDays size={18}/><span>Arribo estimado<strong>{shortDate(active.eta)} <small>{active.eta?active.eta.slice(0,4):''}</small></strong></span><span className="eta-tag">ETA</span></div><button className="btn full" onClick={()=>openFile(active.id)}>Abrir expediente <ArrowUpRight size={15}/></button></div></section>}
 <section className="help-card"><ShieldCheck size={21}/><div><strong>Información, con respaldo.</strong><p>Validá documentos y dejá registro de cada cambio.</p><button onClick={()=>navigate('documents')}>Ir a documentación <ArrowRight size={14}/></button></div></section></div></div>
 <section className="document-overview"><div><h2>Documentación a mano.</h2><p>Los documentos de <strong>{active?.id}</strong>, a un clic.</p></div><div className="doc-quick-grid">{active?.documents.slice(0,3).map((d,i)=><button key={d.id} className={'doc-quick color-'+i} onClick={()=>openFile(active.id,'documents')}><span><FileText size={24}/></span><div><strong>{d.id==='transport'?'Documento de transporte':d.label}</strong><small>{DOC_STATUS[d.status]}</small></div><ArrowUpRight size={16}/></button>)}</div></section>
 </>}
 {page==='shipments'&&<section className="panel"><div className="list-toolbar"><div className="segmented">{[['ALL','Todos'],['IMPORT','Importación'],['EXPORT','Exportación']].map(([v,l])=><button className={direction===v?'active':''} onClick={()=>setDirection(v)} key={v}>{l}</button>)}</div><div className="toolbar-right"><select aria-label="Filtrar estado" value={filter} onChange={e=>setFilter(e.target.value)}><option value="ALL">Todos los estados</option><option value="CUSTOMS_PENDING">Pendientes de libramiento</option>{Object.entries(STATUS).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select><button className="btn" onClick={exportOps}><Download size={15}/>Exportar</button></div></div>{table()}</section>}
 {page==='tasks'&&<><div className="section-intro"><span><b>{pendingTasks.length}</b> pendientes · <b>{data.tasks.filter(t=>t.done).length}</b> completadas</span><label className="inline-check"><input type="checkbox" checked={showAll} onChange={e=>setShowAll(e.target.checked)}/> Mostrar completadas</label></div><section className="panel">{taskList(data.tasks.filter(t=>showAll||!t.done))}</section><p className="muted-note">Las tareas son recordatorios operativos. Completarlas no modifica el estado aduanero ni el transporte.</p></>}
 {page==='quotes'&&<div className="quote-grid">{data.quotes.map(q=><section key={q.id} className="panel quote-card"><div className="quote-top"><span className="ref-link">{q.id}</span><span className="plain-badge">{q.status}</span></div><h2>{q.customer}</h2><p>{q.origin} <ArrowRight size={14}/> {q.destination}</p><div className="quote-tags"><span>{DIRECTIONS[q.direction]}</span><span>{MODES[q.mode]}</span><span>{q.incoterm}</span></div><div className="quote-value"><small>Propuesta · USD</small><strong>{money(q.sell)}</strong><span>Costo {money(q.buy)} · Margen {money(q.sell-q.buy)}</span></div><p className="quote-notes">{q.notes}</p><div className="quote-footer"><span>Válida hasta {shortDate(q.validUntil)}</span><button className="btn primary" disabled={q.status==='Aceptada'||daysUntil(q.validUntil)<0} onClick={()=>{setModal({type:'acceptQuote',quote:q});}}>{q.status==='Aceptada'?'Convertida':daysUntil(q.validUntil)<0?'Vencida':'Crear embarque'}<ArrowUpRight size={14}/></button></div></section>)}</div>}
 {page==='documents'&&<section className="panel"><div className="panel-heading"><div><h2>Control documental</h2><p>Recibido y verificado son estados distintos.</p></div><span className="plain-badge">{ops.reduce((n,o)=>n+o.documents.filter(d=>d.status==='PENDING').length,0)} pendientes</span></div><div className="table-scroll"><table><thead><tr><th>Embarque</th><th>Cliente</th><th>Verificados</th><th>Por revisar</th><th/></tr></thead><tbody>{ops.map(o=><tr key={o.id}><td><button className="ref-link" onClick={()=>openFile(o.id,'documents')}>{o.id}</button><small>{DIRECTIONS[o.direction]} · {MODES[o.mode]}</small></td><td>{o.customer}</td><td><span className="document-progress"><span style={{width:(o.documents.filter(d=>d.status==='VERIFIED').length/o.documents.filter(d=>d.status!=='NA').length*100)+'%'}}/></span>{o.documents.filter(d=>d.status==='VERIFIED').length} / {o.documents.filter(d=>d.status!=='NA').length}</td><td>{o.documents.filter(d=>['PENDING','RECEIVED'].includes(d.status)).length}</td><td><button className="btn" onClick={()=>openFile(o.id,'documents')}>Ver documentos <ChevronRight size={14}/></button></td></tr>)}</tbody></table></div></section>}
 {page==='customers'&&<div className="customer-grid">{[...new Set(ops.map(o=>o.customer))].map(name=>{const list=ops.filter(o=>o.customer===name);return <section key={name} className="panel customer-card"><span className="customer-icon"><Building2 size={25}/></span><h2>{name}</h2><p>Cliente ilustrativo · Datos de ejemplo</p><div><span><b>{list.length}</b> embarques</span><span><b>{list.filter(o=>o.status!=='DELIVERED').length}</b> activos</span></div><button className="btn full" onClick={()=>{navigate('shipments');setQuery(name);}}>Ver operaciones <ArrowRight size={15}/></button></section>})}</div>}
 {page==='reports'&&<><section className="report-kpis">{[['Compra estimada',ops.reduce((n,o)=>n+o.costs.reduce((a,c)=>a+c.buy,0),0)],['Venta estimada',ops.reduce((n,o)=>n+o.costs.reduce((a,c)=>a+c.sell,0),0)],['Margen estimado',ops.reduce((n,o)=>n+o.costs.reduce((a,c)=>a+c.sell-c.buy,0),0)]].map(([label,v])=><article className="panel" key={label}><small>{label} · USD</small><strong>{money(v)}</strong></article>)}</section><section className="panel"><div className="panel-heading"><h2>Costos por embarque</h2><button className="btn" onClick={()=>exportCsv([['Referencia','Cliente','Compra USD','Venta USD','Margen USD'],...ops.map(o=>[o.id,o.customer,o.costs.reduce((a,c)=>a+c.buy,0),o.costs.reduce((a,c)=>a+c.sell,0),o.costs.reduce((a,c)=>a+c.sell-c.buy,0)])],'Atlas_Cargo_Costos_DEMO.csv')}><Download size={15}/>Exportar</button></div><div className="table-scroll"><table><thead><tr><th>Embarque</th><th>Cliente</th><th>Compra USD</th><th>Venta USD</th><th>Margen USD</th></tr></thead><tbody>{ops.map(o=><tr key={o.id}><td><button className="ref-link" onClick={()=>openFile(o.id,'costs')}>{o.id}</button></td><td>{o.customer}</td><td>{money(o.costs.reduce((a,c)=>a+c.buy,0))}</td><td>{money(o.costs.reduce((a,c)=>a+c.sell,0))}</td><td className="positive">{money(o.costs.reduce((a,c)=>a+c.sell-c.buy,0))}</td></tr>)}</tbody></table></div></section><p className="muted-note">Estimaciones operativas. No constituyen una liquidación aduanera ni incluyen automáticamente tributos, percepciones, impuestos o diferencias de cambio.</p></>}
 {page==='settings'&&<section className="panel settings-panel"><h2>Atlas Cargo · Demostración</h2><p>Esta versión permite evaluar el diseño y los flujos de trabajo. Los datos y archivos se guardan únicamente en este navegador; no se comparten entre dispositivos o usuarios.</p><div className="setting-row"><div><strong>Fecha de la demostración</strong><p>30 de octubre de 2026. Las alertas de ejemplo usan esta fecha.</p></div><CalendarDays size={22}/></div><div className="setting-row"><div><strong>Operaciones reales</strong><p>Pendiente: base online, usuarios y permisos conectados. ARCA, navieras y correos no están integrados en esta demo.</p></div><span className="plain-badge">Sin conexión</span></div><div className="setting-row"><div><strong>Descargar respaldo de la demo</strong><p>Exporta operaciones, tareas y cotizaciones. Los archivos adjuntos permanecen en el navegador.</p></div><button className="btn" onClick={()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='Atlas_Cargo_Demo.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}}><Download size={15}/>Descargar</button></div><div className="setting-row"><div><strong>Volver a los datos de ejemplo</strong><p>Elimina los cambios locales realizados en la demo.</p></div><button className="btn danger" onClick={()=>setModal('reset')}><RotateCcw size={15}/>Restablecer</button></div><a className="source-link" href="https://github.com/maxdnik/atlascargo/tree/codex/atlas-operations-20261030/portal" target="_blank" rel="noreferrer">Ver código del proyecto <ExternalLink size={14}/></a></section>}
 <footer className="footer"><span><span className="footer-mark">A</span> ATLAS CARGO <i>© 2026</i></span><span>Datos de ejemplo · Guardado en este navegador <span className={'save-dot '+(storageError?'error':'')}/></span><a href="https://www.atlas-cargo-logistics.com" target="_blank" rel="noreferrer">Nuestro sitio <ArrowUpRight size={12}/></a></footer>
 </main></div>
 {toast&&<div className="toast" role="status"><CheckCheck size={18}/>{toast}</div>}
 {modal==='about'&&<Modal title="Tu operación, en un solo lugar." subtitle="Una demostración interactiva de Atlas Cargo" onClose={()=>setModal(null)}><div className="modal-body"><p>Recorré embarques, creá operaciones de prueba, registrá tareas y probá el control documental. La estética toma la identidad de Atlas Cargo y el modelo operativo parte del ERP existente.</p><div className="info-box"><Info size={20}/><p>Todo lo que ves es ilustrativo. Tus cambios se conservan en este navegador. Esta demo no envía emails, no transmite declaraciones a ARCA y no consulta tracking automático.</p></div><h3>Preparada para los tres equipos</h3><ul className="feature-list"><li><Ship/>Agente de cargas: booking, transporte, fechas y contenedores.</li><li><Building2/>Despachante: destinación, canal, NCM y libramiento.</li><li><Package/>Importador / exportador: documentación, hitos y costos.</li></ul><button className="btn primary full" onClick={()=>setModal(null)}>Explorar la plataforma <ArrowRight size={16}/></button></div></Modal>}
 {modal==='alerts'&&<Modal title="Alertas operativas" subtitle="Seguimiento de vencimientos · Fecha demo: 30 oct 2026" onClose={()=>setModal(null)}><div className="modal-body alert-list">{alerts.map(a=><button key={a.id} className={'alert-item '+a.level} onClick={()=>openFile(a.op,a.kind==='docs'?'documents':'summary')}><TriangleAlert size={20}/><span><strong>{a.title}</strong><small>{a.detail}</small></span><ChevronRight size={17}/></button>)}{!alerts.length&&<p>No hay alertas pendientes.</p>}<p className="muted-note">Los días libres y el almacenaje se registran según las condiciones acordadas con cada proveedor.</p></div></Modal>}
 {modal==='filters'&&<Modal title="Filtrar embarques" onClose={()=>setModal(null)}><div className="modal-body"><Field label="Estado del transporte"><select value={filter} onChange={e=>setFilter(e.target.value)}><option value="ALL">Todos</option><option value="CUSTOMS_PENDING">Pendientes de libramiento</option>{Object.entries(STATUS).map(([k,v])=><option value={k} key={k}>{v}</option>)}</select></Field><button className="btn primary full" onClick={()=>setModal(null)}>Aplicar filtros</button></div></Modal>}
 {modal==='reset'&&<Modal title="¿Restablecer la demostración?" onClose={()=>setModal(null)}><div className="modal-body"><p>Se eliminarán tus cambios y archivos locales y volverán las operaciones de ejemplo.</p><div className="form-actions"><button className="btn" onClick={()=>setModal(null)}>Cancelar</button><button className="btn danger" onClick={async()=>{try{await clearFiles();setData(migrateDemoData(initialState()));setSelected('AT-260038');setModal(null);notify('Demostración restablecida');}catch{notify('No se pudo restablecer. Volvé a intentar.');}}}>Restablecer datos</button></div></div></Modal>}
 {modal==='newOperation'&&<OperationForm onClose={()=>setModal(null)} onSave={o=>{setData(p=>({...p,operations:[o,...p.operations]}));setSelected(o.id);setPage('shipments');setQuery('');setModal(null);notify('Embarque de prueba creado');}} existing={ops}/>}
 {modal==='newTask'&&<Modal title="Nueva tarea" subtitle="Asigná una acción concreta a un embarque." onClose={()=>setModal(null)}><form className="modal-body" onSubmit={e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));setData(p=>({...p,tasks:[{...f,id:uid(),done:false},...p.tasks]}));setModal(null);notify('Tarea creada');}}><Field label="Tarea"><input name="title" required maxLength={160} placeholder="Ej. Confirmar turno de retiro"/></Field><div className="form-grid"><Field label="Embarque"><select name="op">{ops.map(o=><option key={o.id}>{o.id}</option>)}</select></Field><Field label="Responsable"><input name="owner" required defaultValue="Operaciones" maxLength={80}/></Field><Field label="Vencimiento"><input type="date" name="due" required defaultValue={TODAY}/></Field><Field label="Prioridad"><select name="priority"><option>Media</option><option>Alta</option><option>Baja</option></select></Field></div><button className="btn primary full" type="submit">Crear tarea</button></form></Modal>}
 {modal==='newQuote'&&<QuoteForm onClose={()=>setModal(null)} onSave={q=>{setData(p=>({...p,quotes:[q,...p.quotes]}));setModal(null);notify('Cotización creada');}}/>}
 {modal?.type==='acceptQuote'&&<Modal title="Convertir cotización en embarque" subtitle={modal.quote.id+' · '+modal.quote.customer} onClose={()=>setModal(null)}><div className="modal-body"><p>Se creará un expediente en preparación con los datos comerciales de esta propuesta. Las fechas, documentación y condiciones operativas quedarán pendientes de completar.</p><button className="btn primary full" onClick={()=>{const q=modal.quote;const o=makeOperation({...q,customer:q.customer,costs:[{id:uid(),concept:'Propuesta '+q.id,buy:q.buy,sell:q.sell,currency:'USD'}]},ops);setData(p=>({...p,operations:[o,...p.operations],quotes:p.quotes.map(x=>x.id===q.id?{...x,status:'Aceptada'}:x)}));setModal(null);setSelected(o.id);navigate('shipments');notify('Embarque creado desde '+q.id);}}>Confirmar y crear embarque <ArrowRight size={16}/></button></div></Modal>}
 {modal==='detail'&&active&&<Detail op={active} tab={detailTab} setTab={setDetailTab} onClose={()=>setModal(null)} update={(patch,message)=>updateOp(active.id,patch,message)} notify={notify}/>}
 </div>;
}

function makeOperation(f,existing){const max=Math.max(260000,...existing.map(o=>Number(o.id.replace('AT-',''))).filter(Number.isFinite));return {...f,customerId:f.customerId||'client-'+uid(),id:'AT-'+(max+1),status:'DRAFT',customs:'PENDING',channel:'Sin asignar',bookingDate:'',originCode:'',destinationCode:'',notes:'',documents:checklist(f.direction,f.mode),costs:f.costs||[],history:[{date:new Date().toISOString(),text:'Expediente creado en demostración',by:'Usuario demo'}]};}
function CustomerField({existing}){const [id,setId]=useState('');const customers=[...DEMO_CUSTOMERS];for(const op of existing){if(op.customerId&&!customers.some(c=>c.id===op.customerId))customers.push({id:op.customerId,name:op.customer});}return <Field label="Cliente / razón social"><select name="customerId" value={id} onChange={e=>setId(e.target.value)}><option value="">Nuevo cliente</option>{customers.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select>{id?<input type="hidden" name="customer" value={customers.find(c=>c.id===id)?.name||''}/>:<input name="customer" required maxLength={100} placeholder="Razón social del nuevo cliente"/>}</Field>}
function OperationForm({onClose,onSave,existing}){const[dir,setDir]=useState('IMPORT'),[mode,setMode]=useState('OCEAN'),[err,setErr]=useState('');return <Modal wide title="Nuevo embarque" subtitle="Abrí el expediente. Completá el resto a medida que avanza la operación." onClose={onClose}><form className="modal-body" onSubmit={e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));if(f.cuit&&!validCuit(f.cuit)){setErr('El CUIT no tiene un dígito verificador válido.');return;}if(f.eta&&f.etd&&f.eta<f.etd){setErr('La ETA no puede ser anterior a la ETD.');return;}if(['AIR','ROAD'].includes(mode)&&['FOB','CFR','CIF','FAS'].includes(f.incoterm)){setErr('Para transporte aéreo o terrestre elegí un Incoterm multimodal, como FCA, CPT o CIP.');return;}onSave(makeOperation({...f,direction:dir,mode},existing));}}><div className="direction-cards">{[['IMPORT','Importación','Del mundo a Argentina',ArrowDownLeft],['EXPORT','Exportación','De Argentina al mundo',ArrowUpRight]].map(([v,l,s,I])=><button type="button" key={v} className={dir===v?'chosen':''} onClick={()=>setDir(v)}><I size={23}/><span><strong>{l}</strong><small>{s}</small></span>{dir===v&&<Check size={17}/>}</button>)}</div><div className="form-grid"><CustomerField existing={existing}/><Field label="CUIT del cliente" hint="Opcional durante la preparación"><input name="cuit" maxLength={13} placeholder="30-12345678-9"/></Field><Field label="Modalidad"><select value={mode} onChange={e=>setMode(e.target.value)}>{Object.entries(MODES).map(([v,l])=><option value={v} key={v}>{l}</option>)}</select></Field><Field label="Responsable"><input name="responsible" defaultValue="Operaciones" required maxLength={80}/></Field><Field label="Origen"><input name="origin" required placeholder={dir==='IMPORT'?'Shanghai':'Buenos Aires'} maxLength={80}/></Field><Field label="Destino"><input name="destination" required placeholder={dir==='IMPORT'?'Buenos Aires':'Rotterdam'} maxLength={80}/></Field><Field label="Incoterm® 2020"><select name="incoterm" defaultValue="FCA">{['EXW','FCA','FAS','FOB','CFR','CIF','CPT','CIP','DAP','DPU','DDP'].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Lugar / puerto convenido"><input name="namedPlace" required placeholder="Ej. Puerto de Shanghai" maxLength={100}/></Field><Field label="Salida estimada · ETD"><input name="etd" type="date"/></Field><Field label="Arribo estimado · ETA"><input name="eta" type="date"/></Field><Field label="Descripción de mercadería" wide><input name="commodity" required maxLength={200} placeholder="Descripción comercial de la carga"/></Field></div>{err&&<p className="form-error" role="alert">{err}</p>}<div className="form-actions"><span className="muted-note">Se guardará sólo en este navegador.</span><button className="btn" type="button" onClick={onClose}>Cancelar</button><button className="btn primary" type="submit"><Plus size={16}/>Crear embarque</button></div></form></Modal>}
function QuoteForm({onClose,onSave}){return <Modal wide title="Nueva cotización" subtitle="Valores en USD · La propuesta no incluye tributos automáticamente." onClose={onClose}><form className="modal-body" onSubmit={e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));onSave({...f,customerId:f.customerId||'client-'+uid(),id:'COT-'+Date.now().toString().slice(-7),buy:Number(f.buy),sell:Number(f.sell),status:'Borrador'});}}><div className="form-grid"><CustomerField existing={[]}/><Field label="Operación"><select name="direction"><option value="IMPORT">Importación</option><option value="EXPORT">Exportación</option></select></Field><Field label="Modalidad"><select name="mode">{Object.entries(MODES).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></Field><Field label="Incoterm® 2020"><select name="incoterm">{['FCA','FOB','CFR','CIF','CPT','CIP','DAP','DDP'].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Origen"><input name="origin" required maxLength={80}/></Field><Field label="Destino"><input name="destination" required maxLength={80}/></Field><Field label="Compra estimada · USD"><input name="buy" type="number" min="0" step="0.01" required/></Field><Field label="Venta estimada · USD"><input name="sell" type="number" min="0" step="0.01" required/></Field><Field label="Válida hasta"><input name="validUntil" type="date" min={TODAY} required/></Field><Field label="Lugar convenido"><input name="namedPlace" required maxLength={100}/></Field><Field wide label="Alcance y exclusiones"><textarea name="notes" required maxLength={1500} defaultValue="Sujeto a espacio y equipo. Tributos, almacenaje y demoras no incluidos."/></Field></div><button className="btn primary full" type="submit">Guardar cotización</button></form></Modal>}

function Detail({op,tab,setTab,onClose,update,notify}){const[error,setError]=useState(''),[busy,setBusy]=useState(false);const[editing,setEditing]=useState(false);
 useEffect(()=>{setError('');setEditing(false);},[op.id,tab]);
 async function uploadFile(d,file){if(!file)return;if(file.size>5*1024*1024){setError('El archivo supera el límite de 5 MB.');return;}if(!/\.(pdf|png|jpe?g|xlsx?|csv|docx?)$/i.test(file.name)){setError('Elegí un PDF, imagen, planilla o documento Word.');return;}setBusy(true);try{const id=uid();await fileStore('put',{id,file});if(d.fileId)await fileStore('delete',d.fileId);update({documents:op.documents.map(x=>x.id===d.id?{...x,fileId:id,fileName:file.name,status:'RECEIVED',clientVisible:false}:x)},'Documento recibido: '+d.label);setError('');}catch{setError('No se pudo guardar el archivo. Verificá el espacio disponible en el navegador.');}finally{setBusy(false);}}
 async function download(d){if(!d.fileId){notify('Documento ilustrativo: no hay un archivo adjunto. Podés cargar uno de prueba.');return;}try{const row=await fileStore('get',d.fileId);if(!row?.file){notify('El archivo ya no está disponible en este navegador.');return;}const a=document.createElement('a');a.href=URL.createObjectURL(row.file);a.download=d.fileName;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}catch{setError('No se pudo descargar el archivo.');}}
 const dateInput=(label,name)=><Field key={name} label={label}><input name={name} type="date" defaultValue={op[name]||''}/></Field>;
 return <Modal wide title={op.id} subtitle={`${op.customer} · ${DIRECTIONS[op.direction]} · ${MODES[op.mode]}`} onClose={onClose}><div className="detail-route"><span><strong>{op.origin}</strong><ArrowRight size={18}/><strong>{op.destination}</strong></span><Badge status={op.status}/></div><div className="detail-tabs">{[['summary','Operación'],['customs','Aduana'],['documents','Documentos'],['costs','Costos'],['history','Actividad']].map(([v,l])=><button className={tab===v?'active':''} key={v} onClick={()=>setTab(v)}>{l}</button>)}</div><div className="modal-body">
 {tab==='summary'&&<><div className="detail-section-title"><h3>Datos del expediente</h3><button className="btn" onClick={()=>{setEditing(!editing);setError('');}}>{editing?'Cancelar edición':'Editar operación'}</button></div>{editing?<form onSubmit={e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));if(f.eta&&f.etd&&f.eta<f.etd){setError('ETA no puede ser anterior a ETD.');return;}if(f.ata&&f.atd&&f.ata<f.atd){setError('ATA no puede ser anterior a ATD.');return;}if(f.delivered&&(!f.ata||f.delivered<f.ata)){setError('La entrega debe ser posterior al arribo real.');return;}const merged={...op,...f};const err=transitionError(merged,f.status);if(err){setError(err);return;}if(f.status==='DELIVERED'&&!f.delivered){setError('Completá la fecha real de entrega.');return;}if(f.status==='IN_TRANSIT'&&!f.atd){setError('Completá la fecha real de salida (ATD).');return;}if(['ARRIVED','CUSTOMS'].includes(f.status)&&!f.ata){setError('Completá la fecha real de arribo (ATA).');return;}if(f.status==='BOOKING_CONFIRMED'&&!op.bookingDate)f.bookingDate=TODAY;update(f,'Datos operativos y transporte actualizados');setEditing(false);setError('');}}><div className="form-grid"><Field label="Estado del transporte"><select name="status" defaultValue={op.status}>{Object.entries(STATUS).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></Field><Field label="Responsable"><input name="responsible" defaultValue={op.responsible} maxLength={80}/></Field><Field label="Naviera / aerolínea / transportista"><input name="carrier" defaultValue={op.carrier} maxLength={100}/></Field><Field label="Buque / vuelo / viaje"><input name="vessel" defaultValue={op.vessel} maxLength={100}/></Field><Field label="Booking / referencia"><input name="booking" defaultValue={op.booking} maxLength={100}/></Field><Field label="Contenedor / equipo"><input name="container" defaultValue={op.container} maxLength={100}/></Field><Field label="Precinto"><input name="seal" defaultValue={op.seal} maxLength={50}/></Field><Field label="Temperatura acordada (reefer)"><input name="temperature" defaultValue={op.temperature} maxLength={50}/></Field>{[['Salida estimada · ETD','etd'],['Arribo estimado · ETA','eta'],['Salida real · ATD','atd'],['Arribo real · ATA','ata'],['Entrega real','delivered'],['Límite días libres de contenedor','freeUntil'],['Límite almacenaje de terminal','storageUntil'],['Salida de terminal real · Gate-out','gateOut'],['Devolución de vacío real','emptyReturned'],['Cut-off de terminal','cutoff'],['Cut-off VGM','vgm'],['Cut-off shipping instructions','si']].map(([l,n])=>dateInput(l,n))}<Field label="Horario de cut-off · Argentina"><input type="time" name="cutoffTime" defaultValue={op.cutoffTime||''}/></Field><Field label="Observaciones operativas" wide><textarea name="notes" defaultValue={op.notes} maxLength={3000}/></Field></div><p className="muted-note">Días libres y almacenaje son condiciones contractuales distintas. Confirmá fechas con naviera y terminal. Las fechas estimadas no confirman hitos reales.</p><button type="submit" className="btn primary full"><Save size={16}/>Guardar operación</button></form>:<><div className="detail-facts">{[['Modalidad',MODES[op.mode]],['Mercadería',op.commodity],['Incoterm',`${op.incoterm} ${op.namedPlace||''} · 2020`],['Transportista',op.carrier||'A confirmar'],['Booking',op.booking||'A confirmar'],['Equipo',op.container||'No informado'],['Responsable',op.responsible||'Sin asignar'],['Aduana',CUSTOMS[op.customs]],['ETD estimada',shortDate(op.etd)],['ETA estimada',shortDate(op.eta)],['ATD real',op.atd?shortDate(op.atd):'Sin confirmar'],['ATA real',op.ata?shortDate(op.ata):'Sin confirmar'],['Cut-off terminal',op.cutoff?shortDate(op.cutoff)+' · '+(op.cutoffTime||'Hora a confirmar'):'A confirmar'],['Días libres hasta',shortDate(op.freeUntil)],['Almacenaje hasta',shortDate(op.storageUntil)],['Salida de terminal',op.gateOut?shortDate(op.gateOut):'Pendiente / no aplica'],['Devolución de vacío',op.emptyReturned?shortDate(op.emptyReturned):'Pendiente / no aplica']].map(([l,v])=><div key={l}><small>{l}</small><strong>{v}</strong></div>)}</div>{op.notes&&<div className="info-box"><Info size={18}/><p>{op.notes}</p></div>}<div className="info-box"><Anchor size={19}/><p>El estado aduanero se registra por separado. Actualizar el transporte no implica que la mercadería esté librada.</p></div></> }</>}
 {tab==='customs'&&<form onSubmit={e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));if(f.customs==='RELEASED'&&(!f.customsRef||!f.released)){setError('Para registrar el libramiento, completá el número de destinación y la fecha confirmada.');return;}if(f.customs!=='RELEASED'&&op.status==='DELIVERED'){setError('Revisá primero el estado de entrega antes de retirar el libramiento.');return;}update(f,'Registro aduanero actualizado manualmente');setError('');}}><div className="info-box"><ShieldCheck size={20}/><p>{op.direction==='EXPORT'?'Control aduanero en origen: registrá el permiso de embarque y el libramiento antes de la salida internacional.':'Control aduanero de importación: el arribo y el libramiento son hitos independientes.'} Carga manual, sin conexión con SIM/ARCA.</p></div><div className="form-grid"><Field label="Estado aduanero"><select name="customs" defaultValue={op.customs}>{Object.entries(CUSTOMS).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></Field><Field label="Canal de selectividad"><select name="channel" defaultValue={op.channel}>{['Sin asignar','Verde','Naranja','Rojo'].map(x=><option key={x}>{x}</option>)}</select></Field><Field label={op.direction==='EXPORT'?'Permiso de embarque · referencia':'Destinación de importación · referencia'}><input name="customsRef" defaultValue={op.customsRef} maxLength={80} placeholder="Referencia informada por el despachante"/></Field><Field label="Despachante / responsable"><input name="broker" defaultValue={op.broker} maxLength={100}/></Field><Field label="Posición NCM" hint="Clasificación sujeta a validación técnica"><input name="ncm" defaultValue={op.ncm} maxLength={120}/></Field>{dateInput('Fecha de libramiento confirmado','released')}<Field wide label="Intervenciones / observaciones"><textarea name="customsNotes" defaultValue={op.customsNotes} maxLength={3000} placeholder="Organismos intervinientes, restricciones y requisitos particulares de la mercadería"/></Field></div><p className="muted-note">Un canal verde no reemplaza la confirmación del libramiento. Los requisitos y tributos deben verificarse para cada mercadería y régimen.</p><button type="submit" className="btn primary full"><Save size={16}/>Guardar registro aduanero</button><div className="reference-links"><span>Referencias operativas</span><a href="https://serviciosweb.afip.gob.ar/genericos/guiadetramites/VerGuia.aspx?tr=59" target="_blank" rel="noreferrer">ARCA · Declaración y libramiento <ExternalLink size={12}/></a><a href="https://www.argentina.gob.ar/node/41412" target="_blank" rel="noreferrer">Exportación · Control aduanero <ExternalLink size={12}/></a></div></form>}
 {tab==='documents'&&<><div className="info-box"><FolderOpen size={20}/><p>PDF, imágenes, Word y planillas de hasta 5 MB. Archivos guardados en este navegador. Los documentos iniciales son ilustrativos y no tienen archivo adjunto. Marcá “Visible al cliente” para compartir un documento. Al cargar o reemplazar un archivo, queda interno hasta volver a compartirlo.</p></div><div className="docs-list">{op.documents.map(d=><div className="doc-row" key={d.id}><FileText size={24}/><div><strong>{d.label}</strong><small>{d.fileName||'Sin archivo adjunto'}{d.required?' · Requerido':''}</small></div><label className="document-share"><input type="checkbox" checked={d.clientVisible===true} aria-label={'Compartir '+d.label+' con cliente'} onChange={e=>update({documents:op.documents.map(x=>x.id===d.id?{...x,clientVisible:e.target.checked}:x)},(e.target.checked?'Compartido con cliente: ':'Retirado del portal de cliente: ')+d.label)}/>Visible al cliente</label><select aria-label={'Estado de '+d.label} value={d.status} onChange={e=>{if(d.required&&e.target.value==='NA'){setError('Este documento está configurado como requerido.');return;}update({documents:op.documents.map(x=>x.id===d.id?{...x,status:e.target.value}:x)},`${d.label}: ${DOC_STATUS[e.target.value]}`);setError('');}}>{Object.entries(DOC_STATUS).filter(([v])=>!(d.required&&v==='NA')).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select><label className={'icon-btn upload-control '+(busy?'disabled':'')} aria-label={'Cargar '+d.label} title={'Cargar '+d.label}><Upload size={17}/><input aria-label={'Archivo '+d.label} type="file" accept=".pdf,.png,.jpg,.jpeg,.xlsx,.xls,.csv,.doc,.docx" disabled={busy} onChange={e=>{uploadFile(d,e.target.files?.[0]);e.target.value='';}}/></label><button className="icon-btn" onClick={()=>download(d)} title="Descargar archivo" aria-label={'Descargar '+d.label}><Download size={17}/></button></div>)}</div><p className="muted-note">El checklist se adapta a la modalidad y dirección. Certificado de origen e intervenciones se revisan según la mercadería y el régimen. El estado “verificado” es una validación manual.</p></>}
 {tab==='costs'&&<><p className="muted-note">Estimaciones en USD. No se suman monedas diferentes ni se calculan tributos automáticamente.</p><div className="table-scroll"><table><thead><tr><th>Concepto</th><th>Compra</th><th>Venta</th><th>Margen</th></tr></thead><tbody>{op.costs.map(c=><tr key={c.id}><td>{c.concept}</td><td>{money(c.buy)}</td><td>{money(c.sell)}</td><td className={c.sell>=c.buy?'positive':'form-error'}>{money(c.sell-c.buy)}</td></tr>)}</tbody></table></div><form className="cost-form" onSubmit={e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));update({costs:[...op.costs,{...f,id:uid(),buy:Number(f.buy),sell:Number(f.sell),currency:'USD'}]},'Concepto de costo agregado: '+f.concept);e.currentTarget.reset();}}><Field label="Concepto"><input name="concept" required maxLength={100} placeholder="Ej. Transporte local"/></Field><Field label="Compra USD"><input name="buy" type="number" min="0" step="0.01" required/></Field><Field label="Venta USD"><input name="sell" type="number" min="0" step="0.01" required/></Field><button className="btn primary" type="submit"><Plus size={16}/>Agregar</button></form><div className="total-line"><span>Margen estimado de la operación</span><strong>{money(op.costs.reduce((a,c)=>a+c.sell-c.buy,0))} USD</strong></div></>}
 {tab==='history'&&<div className="history-list">{op.history.map((h,i)=><div key={i}><span className="history-icon"><History size={17}/></span><div><strong>{h.text}</strong><small>{h.by} · {new Intl.DateTimeFormat('es-AR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'America/Argentina/Buenos_Aires'}).format(new Date(h.date))}</small></div></div>)}<p className="muted-note">Historial local de demostración; no es un registro de auditoría inalterable.</p></div>}
 {error&&<p className="form-error" role="alert">{error}</p>}
 </div></Modal>;
}
function fileStore(action,value){return new Promise((resolve,reject)=>{const req=indexedDB.open('atlas-demo-documents',1);req.onupgradeneeded=()=>req.result.createObjectStore('files',{keyPath:'id'});req.onerror=()=>reject(req.error);req.onsuccess=()=>{const db=req.result;const tx=db.transaction('files',action==='get'?'readonly':'readwrite');const store=tx.objectStore('files');const result=store[action](value);let output;result.onsuccess=()=>{output=result.result;};tx.oncomplete=()=>{db.close();resolve(output);};tx.onerror=()=>{db.close();reject(tx.error);};};});}
function clearFiles(){return new Promise((resolve,reject)=>{const req=indexedDB.deleteDatabase('atlas-demo-documents');req.onsuccess=()=>resolve();req.onerror=()=>reject(req.error);req.onblocked=()=>reject(new Error('Documentos en uso'));});}
createRoot(document.getElementById('root')).render(<App/>);
